test("responsive screenshot and geometry characterization matrix",{timeout:180000},async()=>{
 fs.mkdirSync(OUT,{recursive:true});const browser=await launch(),report=[];
 try{
  for(const viewport of VIEWPORTS){
   const page=await createPage(browser,viewport);
   try{
    for(const screen of SCREENS){
     await show(page,screen);const geometry=await measure(page),issues=[];
     geometry.safeAreaPadding=await page.evaluate(()=>{const e=document.querySelector(".overlay")||document.querySelector(".showdown-stage")||document.querySelector(".complete-stage")||document.querySelector(".screen"),s=e&&getComputedStyle(e);return s?{top:parseFloat(s.paddingTop),right:parseFloat(s.paddingRight),bottom:parseFloat(s.paddingBottom),left:parseFloat(s.paddingLeft)}:null});
     geometry.resultScrollAccessible=await page.evaluate(()=>{const e=document.querySelector(".result-body");return !!e&&e.scrollHeight>e.clientHeight+1&&["auto","scroll"].includes(getComputedStyle(e).overflowY)});
     if(geometry.horizontalOverflow>1)issues.push(`horizontal-overflow:${Math.round(geometry.horizontalOverflow)}`);
     if(!geometry.footerVisible)issues.push("footer-clipped");
     if(geometry.timerOverlap)issues.push("timer-overlap");
     const inaccessibleClips=geometry.clipped.filter(x=>!(geometry.resultScrollAccessible&&/^(standings|answer-panel)/.test(String(x.selector))));
     if(inaccessibleClips.length)issues.push(...inaccessibleClips.map(x=>`clipped:${String(x.selector).split(" ")[0]}`));
     if(geometry.undersizedControls.length)issues.push(...geometry.undersizedControls.map(x=>`touch-target:${x.label||"unnamed"}:${Math.round(x.width)}x${Math.round(x.height)}`));
     if(geometry.safeAreaPadding&&Object.values(geometry.safeAreaPadding).some(x=>x<10))issues.push("safe-area-padding-under-10");
     if(geometry.contentScroll&&geometry.contentScroll.scroll>geometry.contentScroll.client+1&&geometry.contentScroll.overflow==="hidden")issues.push("hidden-required-scroll");
     if(viewport.width>viewport.height&&geometry.primaryWidthRatio!=null&&geometry.primaryWidthRatio<.48)issues.push(`landscape-underuse:${geometry.primaryWidthRatio.toFixed(2)}`);
     report.push({viewport,screen,reference:viewport.width>viewport.height&&LANDSCAPE_REFERENCES.has(screen),issues,geometry});
     if(process.env.LOS_SCREENSHOTS==="1"||issues.length||LANDSCAPE_REFERENCES.has(screen))await page.screenshot({path:path.join(OUT,`${viewport.name}__${screen}.png`),animations:"disabled"})
    }
   }finally{await page.close()}
  }
 }finally{await browser.close()}
 fs.writeFileSync(path.join(OUT,"report.json"),JSON.stringify(report,null,2));
 assert.equal(report.length,VIEWPORTS.length*SCREENS.length);
 assert.equal(report.filter(x=>x.reference).length,VIEWPORTS.filter(v=>v.width>v.height).length*LANDSCAPE_REFERENCES.size);
 assert.ok(report.some(x=>x.issues.length),"characterization stress fixtures should expose current responsive findings")
});

