   await show(page,"ready");let x=await page.evaluate(()=>{const q=s=>document.querySelector(s),r=e=>e.getBoundingClientRect(),live=r(q(".wc-showtime-live")),board=r(q(".wc-master-board")),button=r(q(".wc-showtime-start"));return{kicker:parseFloat(getComputedStyle(q(".wc-showtime-kicker")).fontSize),its:parseFloat(getComputedStyle(q(".wc-showtime-live h1 span")).fontSize),title:parseFloat(getComputedStyle(q(".wc-showtime-live h1 strong")).fontSize),rule:parseFloat(getComputedStyle(q(".wc-showtime-rule")).fontSize),summary:parseFloat(getComputedStyle(q(".wc-showtime-summary")).fontSize),status:parseFloat(getComputedStyle(q(".wc-showtime-status")).fontSize),button:{width:button.width,height:button.height},utilization:live.width/board.width,inside:live.left>=board.left&&live.right<=board.right&&live.top>=board.top&&live.bottom<=board.bottom,horizontal:document.documentElement.scrollWidth-innerWidth,vertical:document.documentElement.scrollHeight-innerHeight}});assert.ok(x.kicker>=11.5&&x.its>=25&&x.title>=50&&x.rule>=12&&x.summary>=9.5&&x.status>=9.4,`${viewport.name} Showtime scale ${JSON.stringify(x)}`);assert.ok(x.button.width>=180&&x.button.height>=50);assert.ok(x.utilization>=.88);assert.equal(x.inside,true);assert.ok(x.horizontal<=1&&x.vertical<=1);if(viewport.name==="932x430")await page.screenshot({path:path.join(out,"932x430-showtime.png"),animations:"disabled"});
   await show(page,"eliminated");x=await page.evaluate(()=>{const back=document.querySelector("#back"),r=back.getBoundingClientRect(),s=getComputedStyle(back);return{display:s.display,pointer:s.pointerEvents,area:r.width*r.height,horizontal:document.documentElement.scrollWidth-innerWidth,vertical:document.documentElement.scrollHeight-innerHeight}});assert.equal(x.display,"none");assert.equal(x.pointer,"none");assert.equal(x.area,0);assert.ok(x.horizontal<=1&&x.vertical<=1);if(viewport.name==="932x430")await page.screenshot({path:path.join(out,"932x430-eliminated.png"),animations:"disabled"});
   for(const outcome of ["pass","timeout"]){await page.evaluate(outcome=>{const a=window.__RESPONSIVE__,s=a.state;a.clearRuntime();s.voiceOn=false;s.players=[{id:"p1",name:"Alex",avatar:"wc-a1"},{id:"p2",name:"Blair"}];s.game={players:s.players.map(p=>({...p,correct:1,wrong:0,timeout:0,strikes:1,eliminated:false})),startingCount:2,idx:0,qnum:1,used:[],current:{id:"landscape-polish",q:"Test",a:"Nottingham",cat:"General"},answered:true,started:Date.now(),speechLog:[],lastSpeechLog:[],showdown:false,lastOutcomeDetail:outcome==="pass"?"pass":""};a.result(outcome)},outcome);x=await page.evaluate(()=>{const strike=document.querySelector(".wc-timeout-strike"),answer=document.querySelector(".answer-big"),sr=strike.getBoundingClientRect(),ar=answer.getBoundingClientRect(),font=parseFloat(getComputedStyle(strike,"::before").fontSize);return{top:sr.top,bottom:sr.bottom,center:sr.left+sr.width/2,gap:sr.top-ar.bottom,font,inside:sr.top>=0&&sr.bottom<=innerHeight,horizontal:document.documentElement.scrollWidth-innerWidth,vertical:document.documentElement.scrollHeight-innerHeight}});assert.equal(x.inside,true,`${viewport.name}/${outcome} X outside`);assert.ok(Math.abs(x.center-viewport.width/2)<=1);assert.ok(x.gap>=8,`${viewport.name}/${outcome} answer/X gap ${x.gap}`);assert.ok(x.font>=36&&x.font<=56,`${viewport.name}/${outcome} X font ${x.font}`);assert.ok(x.horizontal<=1&&x.vertical<=1);if(viewport.name==="932x430")await page.screenshot({path:path.join(out,`932x430-${outcome}.png`),animations:"disabled"})}
